(()=>{const tr=19;PT8.launch({mode:'mp',track:tr,laps:3,humans:[{id:'merc',alt:0}],ai:PT8.makeAI({n:7,classes:['A'],skill:.88,rally:false}),trackRace:true});
 RACE.cars.forEach(c=>{if(c.human){c.forceAI=1;c.ai={skill:1,lat:0,name:'T'}}});const T=RACE.T,N=T.N,RL=PT8.racingLine(T);
 const tr_=RACE.cars.map(()=>[]);for(let f=0;f<60*130;f++){step(1/60);if(RACE.state==='count'&&f>30)RACE.state='race';if(f%6===0)RACE.cars.forEach((c,i)=>tr_[i].push([+c.x.toFixed(1),+c.z.toFixed(1),+(c.sp).toFixed(1),+(c.in.th||0).toFixed(1),+(c.in.br||0).toFixed(1)]))}
 const line=[],cen=[],L=[],Rr=[];for(let i=0;i<N;i++){const s=Math.sin(T.psi[i]),co=Math.cos(T.psi[i]);line.push([+(T.x[i]+co*RL[i]).toFixed(1),+(T.z[i]-s*RL[i]).toFixed(1)]);L.push([+(T.x[i]+co*T.hw[i]).toFixed(1),+(T.z[i]-s*T.hw[i]).toFixed(1)]);Rr.push([+(T.x[i]-co*T.hw[i]).toFixed(1),+(T.z[i]+s*T.hw[i]).toFixed(1)])}
 return JSON.stringify({tr:tr_,line,L,R:Rr,sk:RACE.cars.map(c=>c.ai&&c.ai.skill)})})()
